import{K as i,a as r,c as n,b as a,k as l,q as c,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"PowerPoint 动画、切换与媒体","description":"区分页面切换和对象动画，用动画窗格安排逐步讲解、触发顺序、持续时间和媒体播放，并检查兼容与导出效果。","frontmatter":{"title":"PowerPoint 动画、切换与媒体","description":"区分页面切换和对象动画，用动画窗格安排逐步讲解、触发顺序、持续时间和媒体播放，并检查兼容与导出效果。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · PowerPoint 演示制作","summary":"区分页面切换和对象动画，用动画窗格安排逐步讲解、触发顺序、持续时间和媒体播放，并检查兼容与导出效果。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"PowerPoint 表格、图表与 Excel 数据关联","link":"/tools/office/powerpoint/data"},"next":{"text":"PowerPoint 放映、演讲者视图与交付","link":"/tools/office/powerpoint/present"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"PowerPoint 表格、图表与 Excel 数据关联","link":"/tools/office/powerpoint/data"},"next":{"text":"PowerPoint 放映、演讲者视图与交付","link":"/tools/office/powerpoint/present"}},"headers":[],"relativePath":"tools/office/powerpoint/animation.md","filePath":"tools/office/powerpoint/animation.md"}'),h={name:"tools/office/powerpoint/animation.md"},k=Object.assign(h,{setup(p){const o={path:"/tools/office/powerpoint/animation",app:"PowerPoint",title:"按讲述顺序显示四个流程步骤",steps:[{tab:"动画",command:"添加动画",setting:"对象：四个步骤框；效果：出现",anchor:"walkthrough-1"},{tab:"动画",command:"动画窗格",setting:"顺序：录入 → 检查 → 汇总 → 交付",anchor:"walkthrough-2"},{tab:"幻灯片放映",command:"从当前幻灯片开始",setting:"逐次单击；再检查静态 PDF",anchor:"walkthrough-3"}]};return(d,e)=>{const t=i("OfficeGuide");return r(),n("div",null,[e[0]||(e[0]=a("h1",{id:"powerpoint-动画、切换与媒体",tabindex:"-1"},[l("PowerPoint 动画、切换与媒体 "),a("a",{class:"header-anchor",href:"#powerpoint-动画、切换与媒体","aria-label":'Permalink to "PowerPoint 动画、切换与媒体"'},"​")],-1)),e[1]||(e[1]=a("p",null,"动画应帮助听众跟上讲解。解释流程时逐步出现有价值；装饰性旋转和频繁闪动容易打断注意力。本篇在四步流程上安排简单逐步出现，再验证视频与导出效果。",-1)),c(t,{guide:o}),e[2]||(e[2]=s('<h2 id="difference" tabindex="-1">切换和动画的区别 <a class="header-anchor" href="#difference" aria-label="Permalink to &quot;切换和动画的区别 {#difference}&quot;">​</a></h2><p>切换作用于两张幻灯片之间，动画作用于当前页的对象。设置“淡化”切换不会让页内四个节点逐个出现；给节点加“出现”动画也不会改变两页之间的切换方式。</p><p>整体演示通常选少量一致的切换效果，时长以不打断内容为准。复杂变形效果如平滑切换依赖版本和对象匹配，应在目标设备检查；没有必要时简单切换更便于维护。</p><h2 id="sequence" tabindex="-1">给流程添加动画 <a class="header-anchor" href="#sequence" aria-label="Permalink to &quot;给流程添加动画 {#sequence}&quot;">​</a></h2><ol><li>选择第一个流程节点，打开“动画”，选择“出现”或温和的进入效果。</li><li>打开动画窗格，确认效果对应正确对象。</li><li>为其余节点添加相同效果；需要同一对象拥有多个效果时使用“添加动画”，避免替换已有动画。</li><li>把顺序调整为收集、校验、汇总、发布，并检查连接箭头是否在合适时刻出现。</li><li>开始方式设为单击时、与上一动画同时或上一动画之后，按实际讲解节奏选择。</li><li>在放映模式从头演示，不能只在动画窗格预览一次就认定顺序正确。</li></ol><p>逐段出现的文本还需要检查效果选项和段落级别。手工文本框和占位符的动画行为可能不同，应以实际放映结果为准。</p><h2 id="timing" tabindex="-1">控制时间与触发 <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;控制时间与触发 {#timing}&quot;">​</a></h2><p>持续时间决定效果本身播放多久，延迟决定开始前等待多久。把两者混淆会导致“点了很久没反应”或动画跑得太快。交互触发器适合点击某按钮显示解释，但复杂触发逻辑会增加误操作，必须检查返回和重复点击的行为。</p><p>现场问答多时，优先保留手动控制；无人值守循环展示才更需要自动换页。使用排练计时时，确认播放是否启用记录的计时，否则现场可能自动翻到下一页。</p><h2 id="media" tabindex="-1">音频和视频 <a class="header-anchor" href="#media" aria-label="Permalink to &quot;音频和视频 {#media}&quot;">​</a></h2><p>插入媒体后设置开始方式、音量、裁剪和是否跨页播放等选项，再检查文件是否实际包含所需媒体。在线视频依赖网络、服务和权限，不适合把“能在办公室播放”视为会场保证。</p><p>准备离线交付时，使用有权使用且目标环境支持的本地媒体，并在目标电脑试播；必要时准备独立视频作为备用。字幕和清晰旁白有助于理解，不能只依赖背景音乐或视觉动作传达关键步骤。</p><h2 id="practice" tabindex="-1">静态输出与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;静态输出与验收 {#practice}&quot;">​</a></h2><p>PDF 不保留交互动画；动画结束后覆盖在一起的多层对象，静态导出可能变得难读。需要阅读版时，可制作静态布局副本或拆分为多页。导出视频时还要检查录制旁白、计时、声音和清晰度是否包含。</p><p>练习：让四步流程按讲解顺序出现，再故意把第二步设为上一动画之后，观察节奏差异。分别导出 PDF 和短视频，确认 PDF 含完整可读流程，视频的时序和声音符合预期。</p><h2 id="walkthrough" tabindex="-1">图示跟做：按讲述顺序显示四个流程步骤 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：按讲述顺序显示四个流程步骤 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先选择对象再加效果 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先选择对象再加效果 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：动画 → 添加动画。</strong></p><p>在四步流程副本中选中第一个步骤框，使用“动画 → 添加动画”选择简单的出现效果，再处理后面的框。想在已有对象上叠加效果时使用添加动画；直接重新选择效果可能替换原来的动画。先保持一种效果，便于判断顺序。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：在窗格核对目标和顺序 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：在窗格核对目标和顺序 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：动画 → 动画窗格。</strong></p><p>打开动画窗格，按流程重排条目，点击每条确认对应的形状。第一条可设单击时，后续根据讲述节奏选择单击时或上一动画之后。检查连接线是否过早出现、说明文字是否与框一起出现，不要只看效果名称。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：同时验证演示版与阅读版 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：同时验证演示版与阅读版 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：幻灯片放映 → 从当前幻灯片开始。</strong></p><p>从当前页放映，每次单击确认只出现预期对象，按 Esc 退出后再调整。随后导出 PDF，检查所有静态内容叠放后是否仍能理解。依赖先后遮挡才能表达意思的页面，应为阅读版调整布局或拆页，PDF 不会保留动画过程。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>页面自动跳走时同时检查切换选项的自动换片时间和放映使用计时设置。对象动画与页面切换是两套设置，只改其中一处可能还会自动播放。</p>',28))])}}});export{u as __pageData,k as default};
